function minOperationsToMakeMedianK(nums, k) {
  nums.sort((a, b) => a - b);
  const middle = Math.floor(nums.length / 2);
  let operations = Math.abs(nums[middle] - k);

  for (let i = middle - 1; i >= 0 && nums[i] > k; i--) {
    operations += nums[i] - k;
  }
  for (let i = middle + 1; i < nums.length && nums[i] < k; i++) {
    operations += k - nums[i];
  }
  return operations;
}

