function minOperationsToMakeMedianK(nums, k) {
  // Put every element in a class (ends below k, at k, or above k) in all 3^n ways. The median is k exactly when
  // at most floor(n / 2) values end below k and at most n - 1 - floor(n / 2) end above it.
  const n = nums.length;
  const middle = Math.floor(n / 2);
  let best = Infinity;
  const place = (index, below, above, cost) => {
    if (below > middle || above > n - 1 - middle || cost >= best) return;
    if (index === n) { best = cost; return; }
    const value = nums[index];
    place(index + 1, below + 1, above, cost + Math.max(0, value - (k - 1)));
    place(index + 1, below, above, cost + Math.abs(value - k));
    place(index + 1, below, above + 1, cost + Math.max(0, k + 1 - value));
  };
  place(0, 0, 0, 0);
  return best;
}

