function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = int(1500, 2000);
    const nums = Array.from({ length: n }, () => int(1, 1000000000));
    const sorted = [...nums].sort((a, b) => a - b);
    const shape = rand();
    const k = shape < 0.4 ? sorted[int(0, n - 1)] : shape < 0.7 ? int(1, 1000000000) : rand() < 0.5 ? 1 : 1000000000;
    return [nums, k];
  }
  const n = int(1, 8);
  const top = rand() < 0.2 ? 1000000000 : int(1, 12);
  const nums = Array.from({ length: n }, () => int(1, top));
  const k = rand() < 0.3 ? nums[int(0, n - 1)] : int(1, top);
  return [nums, k];
}
